<?php require_once __DIR__ . '/includes/auth.php'; $user=require_role(['tenant_admin','manager','employee']); $pdo=db(); check_tenant_active($pdo); $tid=require_tenant(); $base=''; $active='calendar'; $pageTitle='Calendar';
if (is_post()) { verify_csrf(); if(($_POST['action']??'')==='delete') $pdo->prepare('DELETE FROM events WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tid]);
  else $pdo->prepare('INSERT INTO events(tenant_id,title,description,event_date,project_id,created_by,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute([$tid,trim($_POST['title']??''),$_POST['description']??null,$_POST['event_date']?:date('Y-m-d'),(int)($_POST['project_id']??0)?:null,$user['id']]);
  flash('success','Event saved.'); redirect('calendar.php?month='.($_GET['month']??date('Y-m'))); }
$month=$_GET['month']??date('Y-m'); if(!preg_match('/^\d{4}-\d{2}$/',$month)) $month=date('Y-m');
$start=$month.'-01'; $end=date('Y-m-t',strtotime($start));
$s=$pdo->prepare('SELECT id,title,due_date AS d,"task" AS kind FROM tasks WHERE tenant_id=? AND due_date BETWEEN ? AND ? UNION ALL SELECT id,title,end_date AS d,"project deadline" AS kind FROM projects WHERE tenant_id=? AND end_date BETWEEN ? AND ? UNION ALL SELECT id,title,event_date AS d,"event" AS kind FROM events WHERE tenant_id=? AND event_date BETWEEN ? AND ? UNION ALL SELECT id,title,due_date AS d,"milestone" AS kind FROM milestones WHERE tenant_id=? AND due_date BETWEEN ? AND ? ORDER BY d');
$s->execute([$tid,$start,$end,$tid,$start,$end,$tid,$start,$end,$tid,$start,$end]); $items=$s->fetchAll();
$byDay=[]; foreach($items as $it) $byDay[$it['d']][]=$it;
$s=$pdo->prepare('SELECT id,name FROM projects WHERE tenant_id=? AND status!="archived" ORDER BY name'); $s->execute([$tid]); $projects=$s->fetchAll();
$s=$pdo->prepare('SELECT * FROM events WHERE tenant_id=? ORDER BY event_date DESC LIMIT 10'); $s->execute([$tid]); $events=$s->fetchAll();
$prev=date('Y-m',strtotime($start.' -1 month')); $next=date('Y-m',strtotime($start.' +1 month')); $firstDow=(int)date('N',strtotime($start)); $days=(int)date('t',strtotime($start));
include __DIR__ . '/includes/header.php'; ?>
<div class="d-flex justify-content-between align-items-center mb-3"><h5 class="mb-0"><?= date('F Y',strtotime($start)) ?></h5><div><a class="btn btn-outline-secondary btn-sm" href="?month=<?= $prev ?>">← Prev</a> <a class="btn btn-outline-secondary btn-sm" href="?month=<?= date('Y-m') ?>">Today</a> <a class="btn btn-outline-secondary btn-sm" href="?month=<?= $next ?>">Next →</a></div></div>
<div class="card p-3 mb-3"><div class="row row-cols-7 g-1 text-center fw-bold small"><div class="col">Mon</div><div class="col">Tue</div><div class="col">Wed</div><div class="col">Thu</div><div class="col">Fri</div><div class="col">Sat</div><div class="col">Sun</div></div>
<div class="row row-cols-7 g-1"><?php for($i=1;$i<$firstDow;$i++) echo '<div class="col"></div>'; for($d=1;$d<=$days;$d++): $date=$month.'-'.str_pad((string)$d,2,'0',STR_PAD_LEFT); ?><div class="col"><div class="border rounded p-1 small" style="min-height:92px"><strong class="<?= $date===date('Y-m-d')?'text-primary':'' ?>"><?= $d ?></strong><?php foreach($byDay[$date]??[] as $it): ?><div class="badge bg-<?= $it['kind']==='task'?'primary':($it['kind']==='event'?'success':'warning') ?> text-wrap w-100 my-1" title="<?= e($it['kind']) ?>"><?= e($it['title']) ?></div><?php endforeach; ?></div></div><?php endfor; ?></div></div>
<div class="row g-3"><div class="col-lg-6"><div class="card p-3"><h6>Add event / meeting</h6><form method="post"><?= csrf_field() ?><div class="mb-2"><input class="form-control" name="title" placeholder="Event title" required></div><div class="mb-2"><input class="form-control" type="date" name="event_date" required></div>
<div class="mb-2"><select class="form-select" name="project_id"><option value="">Project (optional)</option><?php foreach($projects as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['name']) ?></option><?php endforeach; ?></select></div>
<div class="mb-2"><input class="form-control" name="description" placeholder="Description / meeting notes"></div><button class="btn btn-primary">Add event</button></form></div></div>
<div class="col-lg-6"><div class="card p-3"><h6>Upcoming / recent events</h6><?php foreach($events as $ev): ?><div class="border-bottom py-2 small d-flex justify-content-between"><span><strong><?= e($ev['title']) ?></strong> · <?= e($ev['event_date']) ?></span><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $ev['id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div><?php endforeach; if(!$events) echo '<p class="text-muted small mb-0">No events yet — deadlines from tasks, projects and milestones appear automatically above.</p>'; ?></div></div></div>
<?php include __DIR__ . '/includes/footer.php'; ?>
